starterCode:
from fastapi import FastAPI, Request

app = FastAPI()
COUNT = {"requests": 0}


@app.middleware("http")
async def count_requests(request: Request, call_next):
    COUNT["requests"] += 1
    response = call_next(request)
    return response


@app.get("/ping")
def ping():
    return {"pong": True}


@app.get("/stats")
def stats():
    return COUNT

